#!/usr/bin/env python3
# luxarch:ledger hook v6 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""Shared helpers for the commit-ledger hooks (record / stop-guard / clear)."""

from __future__ import annotations

import json
import os
import subprocess
import sys
from pathlib import Path


def project_dir() -> Path:
    d = os.environ.get("CLAUDE_PROJECT_DIR")
    if d:
        return Path(d)
    try:
        return Path(
            subprocess.check_output(
                ["git", "rev-parse", "--show-toplevel"],
                text=True,
                stderr=subprocess.DEVNULL,
            ).strip()
        )
    except Exception:
        return Path.cwd()


def tree_dir() -> Path:
    """The checkout the agent is working in: the top of the event's `cwd`, else the project dir.

    An agent works in its issue's worktree (`.claude/worktrees/<ISSUE-KEY>`, --doc
    FLEET-AGENT-CONDUCT-STANDARD, "Concurrent agents: one worktree per issue") while
    CLAUDE_PROJECT_DIR can still name the main checkout, so a `git rev-parse HEAD` run there
    recorded the main checkout's HEAD, not the commit just made."""
    cwd = str(_EVENT.get("cwd") or "")
    if cwd:
        try:
            top = subprocess.check_output(
                ["git", "-C", cwd, "rev-parse", "--show-toplevel"],
                text=True,
                stderr=subprocess.DEVNULL,
            ).strip()
        except Exception:
            top = ""
        if top:
            return Path(top)
    return project_dir()


def state_dir() -> Path:
    """Where session state lives: `.claude/` in the MAIN checkout, shared by every worktree.

    A worktree is removed when its issue lands, and the ledger must outlive it: the commits it
    recorded still have to be logged to LuxPM and pushed from the main checkout."""
    try:
        common = subprocess.check_output(
            [
                "git",
                "-C",
                str(tree_dir()),
                "rev-parse",
                "--path-format=absolute",
                "--git-common-dir",
            ],
            text=True,
            stderr=subprocess.DEVNULL,
        ).strip()
    except Exception:
        common = ""
    if common and Path(common).name == ".git":
        return Path(common).parent / ".claude"
    return project_dir() / ".claude"


def ledger_path() -> Path:
    return state_dir() / ".luxpm-ledger.json"


def read_ledger() -> list[dict[str, object]]:
    try:
        data = json.loads(ledger_path().read_text(encoding="utf-8"))
    except Exception:
        return []
    return data if isinstance(data, list) else []


def write_ledger(entries: list[dict[str, object]]) -> None:
    p = ledger_path()
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(entries, indent=2), encoding="utf-8")


def git(*args: str) -> str:
    try:
        return subprocess.check_output(
            ["git", "-C", str(tree_dir()), *args],
            text=True,
            stderr=subprocess.DEVNULL,
        ).strip()
    except Exception:
        return ""


def session_id() -> str:
    """This agent session's id, from the hook payload if it was read, else the env.

    Claude Code puts `session_id` in every hook event. `read_event()` caches it so a hook that has
    already consumed stdin can still ask. Empty string when unavailable — entries written without a
    session are treated as everyone's, which keeps a pre-upgrade ledger from being ignored.
    """
    # str() at the boundary: the payload is untyped JSON, and an id is only ever compared
    # as a string.
    return str(_EVENT.get("session_id") or os.environ.get("CLAUDE_SESSION_ID", ""))


# A NAMED tuple, not an inline `except (OSError, ValueError)`. Under `target = "py314"` ruff
# formats the inline form to PEP 758's `except OSError, ValueError:`; under py311/py313 it keeps the
# parentheses. So the SAME emitted file has two canonical forms, and an emitted asset is supposed to
# be byte-identical everywhere — in a py314 repo `luxlint --format` rewrote it, `repo.hooks_current`
# then reported drift, and the two guards DEADLOCKED with no local fix.
#
# The fleet declares three targets today (4 guards py311, 7 repos py313, 14 repos py314), so an
# emitted asset must avoid every construct whose canonical formatting is target-dependent. A NAME has
# no parentheses for a formatter to take away.
_PAYLOAD_ERRORS = (OSError, ValueError)

_EVENT: dict[str, object] = {}


def read_event() -> dict[str, object]:
    """Parse the hook event from stdin ONCE and cache it (stdin can only be read once)."""
    global _EVENT
    if not _EVENT:
        try:
            _EVENT = json.load(sys.stdin) or {}
        except _PAYLOAD_ERRORS:
            # Only a missing/malformed payload is tolerated. A bare `except Exception` here hid a
            # NameError (an unimported `sys`) as "no event", so record-commit silently recorded
            # NOTHING while exiting 0 — the same shape as the settings.json data loss.
            _EVENT = {}
    return _EVENT


def mine(entries: list[dict[str, object]]) -> list[dict[str, object]]:
    """The ledger entries belonging to THIS session.

    An entry with no session is included: it predates session stamping, so holding the current agent
    to it is the conservative choice. An entry stamped with a DIFFERENT session is another agent's
    work — it must not block this one, and this one must not log it (that would put wrong commits on
    someone else's ticket).
    """
    me = session_id()
    return [e for e in entries if not e.get("session") or e.get("session") == me]


def others(entries: list[dict[str, object]]) -> list[dict[str, object]]:
    me = session_id()
    return [e for e in entries if e.get("session") and e.get("session") != me]


# ── the LuxPM search marker ───────────────────────────────────────────────────────────────────────────
# A PostToolUse hook records "this session searched LuxPM" the moment a search RETURNS; the
# search-before-create hook reads it. Reading the transcript alone raced Claude Code's flush: the
# search that ran one call earlier was not in the file yet when the create was judged, so 4 of 11
# creates after a search were denied in one session.


def search_marker_path() -> Path:
    return state_dir() / ".luxpm-searched.json"


def _read_marker() -> dict[str, bool]:
    try:
        data = json.loads(search_marker_path().read_text(encoding="utf-8"))
    except _PAYLOAD_ERRORS:
        return {}
    return {str(k): bool(v) for k, v in data.items()} if isinstance(data, dict) else {}


def _write_marker(data: dict[str, bool]) -> None:
    path = search_marker_path()
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(data), encoding="utf-8")


def mark_searched() -> None:
    data = _read_marker()
    data[session_id()] = True
    _write_marker(data)


def clear_searched() -> None:
    data = _read_marker()
    if data.pop(session_id(), None) is not None:
        _write_marker(data)


def has_searched() -> bool:
    return _read_marker().get(session_id(), False)


# ── what each session searched LuxPM FOR (v6) ─────────────────────────────────────────────────────────
# edit-history needs the terms, not just the fact: the first change to a file is allowed once this
# session has searched LuxPM for that file, because a hold on it lives in LuxPM, not in git.


def search_terms_path() -> Path:
    return state_dir() / ".luxpm-search-terms.json"


def _read_terms() -> dict[str, list[str]]:
    try:
        data = json.loads(search_terms_path().read_text(encoding="utf-8"))
    except _PAYLOAD_ERRORS:
        return {}
    return data if isinstance(data, dict) else {}


def record_search_term(term: str) -> bool:
    """Remember a LuxPM search term for this session. False when it cannot be written."""
    term = term.strip()
    if not term or not session_id():
        return False
    data = _read_terms()
    mine = [t for t in data.get(session_id(), []) if isinstance(t, str)]
    if term not in mine:
        mine.append(term)
    data[session_id()] = mine[-1000:]
    try:
        search_terms_path().parent.mkdir(parents=True, exist_ok=True)
        search_terms_path().write_text(json.dumps(data), encoding="utf-8")
    except OSError:
        return False
    return True


def search_terms() -> list[str]:
    return [t for t in _read_terms().get(session_id(), []) if isinstance(t, str)]


def terms_writable() -> bool:
    """Can a search term be remembered here? A gate that waits for one must not wait forever."""
    p = search_terms_path()
    try:
        p.parent.mkdir(parents=True, exist_ok=True)
        if p.exists():
            return p.is_file() and os.access(p, os.W_OK)
        return os.access(p.parent, os.W_OK)
    except OSError:
        return False


def commits_path() -> Path:
    """Every commit an agent session made here, by session, kept until it reaches upstream. Not
    the LuxPM ledger: that one is emptied once the work is logged, and the push guard still has to
    know whose commits are unpushed afterwards."""
    return state_dir() / ".session-commits.json"


def record_session_commit(sha: str, subject: str) -> None:
    p = commits_path()
    try:
        data = json.loads(p.read_text(encoding="utf-8"))
    except Exception:
        data = []
    entries = data if isinstance(data, list) else []
    if any(e.get("sha") == sha for e in entries if isinstance(e, dict)):
        return
    entries.append({"sha": sha, "subject": subject, "session": session_id()})
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(entries[-500:], indent=2), encoding="utf-8")
